from pathlib import Path
import json,shutil
w=Path(__file__).parent
p=json.loads((w/'final-posts.json').read_text(encoding='utf-8')); by={x['id']:x for x in p}
s=json.loads((w/'final-stories.json').read_text(encoding='utf-8'))
backup=w/'antes-revisao-cotidiano'
backup.mkdir(exist_ok=True)
for name in ['final-posts.json','final-stories.json']:
    if not (backup/name).exists():shutil.copy2(w/name,backup/name)
def C(pid,slides,caption,**kw):by[pid].update(title=slides[0][0],slides=slides,caption=caption,**kw)
def I(pid,title,body,visual,caption,**kw):by[pid].update(title=title,text=[title,body],visual=visual,caption=caption,**kw)
def R(pid,title,scenes,caption,**kw):by[pid].update(title=title,cover=title,scenes=[[i*9,(i+1)*9,*row]for i,row in enumerate(scenes)],visual=' '.join(row[0]for row in scenes),caption=caption,**kw)

C('P01',[
('A tarefa é do seu filho. Mas é você que acaba fazendo.','Ele diz “não consigo”. Você começa a explicar e, quando percebe, está dizendo até o que ele deve escrever.','Mãe e filho de 11–12 anos à mesa de casa. Livro aberto e caderno com poucas linhas escritas. Ele segura o lápis; ela escuta. Sem tarefa de artesanato.'),
('Ele precisa fazer um resumo. A página continua em branco.','O pedido da escola é resumir uma história que leu. Antes de ditar a primeira frase, tente descobrir em qual parte ele precisa de ajuda.','Livro aberto ao lado de caderno intitulado Resumo da história. Mostrar página vazia e gesto de hesitação, sem expressão exagerada.'),
('“Me conta o que aconteceu nessa história.”','Ele consegue contar, mas mistura tudo: personagens, detalhes e final. Nesse caso, falta escolher o que entra no resumo e organizar o começo.','Filho conta a história com gestos. Mãe olha para ele, sem escrever em seu lugar. Livro e caderno permanecem abertos.'),
('Ajude a escolher as ideias. Deixe ele escrever.','“Qual foi o principal problema da história? Como terminou?” Ele anota essas ideias e tenta a primeira frase com as próprias palavras.','Detalhe do caderno com duas anotações editoriais: Principal problema / Como terminou. Abaixo, linha começada pela criança. A mãe não segura o lápis.'),
('Criar jogos dá um motivo para organizar ideias.','Para criar um jogo da memória, por exemplo, a criança precisa transformar o que imaginou em regras: virar duas cartas, comparar e manter os pares. Depois, joga para conferir.','Diagrama editorial de duas cartas viradas iguais, baseado na regra do exemplo Jogo da Memoria do Estúdio. Três etapas: Virar duas / Comparar / Manter o par. Não imitar a interface do produto.'),
('A primeira frase pode ser dele.','Você ajuda a organizar o que ele quer dizer. Ele tenta escrever e vocês leem juntos. Se ainda faltar compreensão da história, voltem à leitura antes de continuar.','Filho escreve no próprio caderno; mãe acompanha ao lado. Encerrar na tarefa escolar, sem sugerir que criar jogos substitui ajuda em leitura.')
], 'O filho chama porque não consegue fazer a tarefa. A gente começa explicando e acaba ditando a resposta. É fácil a atividade passar para a mão do adulto.\n\nNo caso de um resumo, peça primeiro que ele conte a história. A resposta ajuda a perceber se precisa voltar à leitura ou se já entendeu o texto e está com dificuldade para organizar o que vai escrever.\n\nSe for essa segunda situação, ajude a escolher as ideias principais e deixe que tente a primeira frase. Depois, leiam juntos.\n\nCriar jogos oferece outra oportunidade de praticar a organização de ideias. No jogo da memória, a criança precisa transformar a ideia da brincadeira em regras que o computador siga. O teste mostra se a sequência funciona.\n\nEssa prática não substitui o apoio na tarefa escolar. É uma forma de trabalhar a habilidade em algo que ela tem interesse em construir.\n\nCenas de família ilustradas; cartas em diagrama editorial.',skill='Organização de ideias: distinguir compreensão da história e planejamento da escrita.',cta='Ouvir o que o filho entendeu e ajudá-lo a escolher um começo, preservando sua autoria.')

C('P06',[
('Seu filho pede ajuda. Você não lembra de aprender daquele jeito.','Ele mostra a conta de matemática. O jeito de resolver no caderno é diferente do que você conhece.','Responsável olha um exercício no caderno do filho, com exemplo resolvido pela professora na página anterior.'),
('Comecem pelo exemplo da aula.','Peça que ele mostre uma conta que já fez com a professora. Vocês têm uma explicação para consultar, em vez de tentar adivinhar o método.','Criança aponta exemplo anterior. Adulto acompanha sem apagar a resolução ou inventar um procedimento diferente.'),
('Peça que mostre até onde acompanhou.','“Qual foi o primeiro passo? Em qual parte você se perdeu?” Talvez ele saiba começar e precise de ajuda num ponto específico.','Caderno aberto, dedo indica uma linha do cálculo. Se mostrar números, conferir o cálculo antes de produzir a arte.'),
('Se a dúvida continuar, registrem onde travou.','Levar essa pergunta à professora é mais útil do que dizer só “não entendi nada”. Você não precisa inventar uma resposta.','Pequeno bilhete junto do exercício com o ponto da dúvida. Não simular conversa real com professora.'),
('Criar um jogo oferece dúvidas que dá para mostrar funcionando.','Num jogo de rebater a bola, seu filho consegue mostrar: “Era para ela voltar, mas atravessou a raquete”. Ele aprende a explicar o problema e procurar o comando que precisa rever.','Usar Pong como base para demonstrar uma alteração preparada pela equipe e sua correção. O exemplo original não deve ser apresentado como defeituoso. Mostrar a passagem pela raquete só após preparar a variação.')
], '“Na minha época era diferente” pode ser uma reação bem real diante do caderno. Vocês podem começar pelo exemplo que a criança já trabalhou na aula.\n\nPeça que mostre o caminho e onde deixou de entender. Se vocês não conseguirem resolver, anotem a dúvida para levar à professora. Participar também é ajudar a fazer uma pergunta mais clara.\n\nCriar jogos pode trabalhar essa habilidade de explicar problemas: a criança compara o que queria com o que aconteceu na tela. Num jogo de rebater a bola, dá para mostrar onde a reação saiu diferente.\n\nEla passa a ter uma dúvida específica para investigar ou levar a quem pode ajudar. A demonstração de Pong será preparada pela equipe; não é relato de aluno.',cta='Consultar o exemplo da aula e localizar a dúvida antes de procurar ajuda.')

I('P07','Ele respondeu “entendi”. Mas ainda não sabe o que precisa entregar.','Peça: “Me conta o que a professora pediu para fazer”.','Filho de 10–13 anos com enunciado de trabalho escolar e caderno. Responsável ouve a explicação do pedido, sem olhar nota ou boletim.',
'O trabalho pede pesquisar um animal e apresentar onde vive, o que come e como se desloca. Seu filho diz que entendeu, mas começa procurando qualquer imagem do animal.\n\nPedir que ele conte o que precisa entregar ajuda a conferir se o pedido ficou claro. Vocês podem anotar os três assuntos antes de abrir a pesquisa.\n\nCriar um jogo de perguntas é uma forma de trabalhar clareza: quem programa precisa escrever uma pergunta que dê para entender e definir qual resposta vale. Outra pessoa joga e mostra se ficou alguma dúvida.\n\nA atividade dá um motivo para cuidar das instruções, porque alguém vai tentar segui-las.',skill='Compreensão de instruções e clareza ao formular perguntas.',cta='Conferir com o filho o que a tarefa pede antes de começar.')

R('P08','Ele quer colocar tudo no trabalho. Ainda não terminou a primeira parte.',[
('Criança planeja apresentação escolar; caderno com várias ideias de imagens e assuntos.','O trabalho cresceu antes de começar.','Seu filho precisa fazer uma apresentação para a escola. Quer vídeo, fotos, animação e um monte de curiosidades. Mas ainda não escolheu o que vai contar.'),
('Adulto e criança leem o pedido e separam os assuntos obrigatórios das ideias extras.','Primeiro, o que precisa ser explicado.','Voltem ao pedido da professora. Escolham os assuntos que precisam entrar. Deixem as ideias extras numa lista para depois.'),
('Criança escreve três tópicos e escolhe uma imagem que explica um deles.','Uma imagem com função.','Se o tema é um animal, comecem por onde vive, o que come e como se desloca. Depois escolham imagens que ajudem a explicar isso.'),
('Só agora, exemplo Mini plataforma no Estúdio, com andar e pular.','Criar jogos dá um motivo para planejar uma primeira versão.','Ao criar um jogo, também é preciso escolher o que fazer primeiro. Antes de inventar dez fases, a criança pode fazer o personagem andar e pular. Testar essa parte dá uma base para continuar.')
], 'Quando o trabalho tem muitas possibilidades, escolher o que vem primeiro já faz parte da tarefa.\n\nComecem pelo que foi pedido. As ideias de vídeo, efeitos e imagens podem ficar numa lista para depois. Assim, o conteúdo ganha um começo antes da decoração.\n\nPlanejar uma primeira versão também é importante na criação de jogos. Fazer o personagem andar e pular é um objetivo que dá para construir e testar antes de pensar em várias fases.\n\nO jogo oferece uma razão para praticar essa escolha: sem a primeira parte funcionando, as próximas ideias ainda não podem ser experimentadas.',cta='Separar o necessário para a entrega das ideias que podem entrar depois.')

C('P09',[
('Ele viu o tutorial inteiro. Agora não sabe por onde começar.','Queria colocar uma imagem na apresentação da escola. Acompanhou o vídeo, abriu o programa e se perdeu no primeiro passo.','Criança com notebook, apresentação escolar e tutorial genérico autorizado, sem artesanato.'),
('No vídeo, tudo já estava no lugar.','Quem explicou já tinha a imagem salva e sabia qual menu abrir. Seu filho precisa localizar o arquivo e encontrar esse caminho.','Comparar pasta com arquivo de imagem e menu real da ferramenta escolhida para gravação. Não inventar botões.'),
('Vale pausar antes de acumular mais passos.','Viu como inserir a imagem? Pause e tente fazer. Agora dá para perceber se a dúvida está em achar o arquivo ou em usar o programa.','Tutorial pausado; criança procura a imagem que vai usar.'),
('Voltar ao vídeo passa a ter um motivo.','Ele encontra o trecho que mostra a ação de que precisa. Faz, confere e só depois continua.','Revisão do trecho correspondente e imagem finalmente inserida no slide escolar.'),
('Aprender a programar um jogo precisa desse tempo de fazer.','A criança vê como fazer o personagem pular, monta o comando e testa. Se ele não pula, há uma ação concreta para comparar com a explicação.','Mini plataforma no Estúdio. Captar montar e testar um comando real, sem sugerir que é um curso específico.')
], 'Um tutorial pode parecer claro enquanto outra pessoa faz tudo. A dúvida aparece quando a criança tenta localizar o arquivo, abrir o menu ou repetir a ação.\n\nPausar depois de um passo dá tempo para fazer essa tentativa. Voltar ao trecho certo responde à dúvida que acabou de aparecer.\n\nCriar jogos torna essa prática visível: programar um pulo só está completo depois de experimentar o movimento. A criança alterna explicação, construção e teste para fazer a própria ideia funcionar.\n\nPor isso, vídeo pausado não significa, por si só, atividade parada.',cta='Pausar um tutorial para executar a ação que acabou de ser explicada.')

C('P10',[
('Ele inventou outro final para o filme. Isso também é criatividade.','Depois de assistir, seu filho conta o que faria diferente: salvaria outro personagem, mudaria a escolha do herói ou deixaria uma pista para continuar.','Responsável e filho conversam depois de um filme. Televisão sem obra protegida visível; foco nos rostos e na conversa.'),
('A ideia começa com algo que ele conhece.','Seu filho já entendeu a história. Agora está imaginando outra possibilidade para ela.','Filho descreve a mudança com gestos. Não usar personagem de franquia como se fosse material próprio.'),
('Vale ouvir o motivo da mudança.','“Por que você queria esse final?” Ele pode estar pensando em justiça, surpresa ou num personagem de que gostou.','Responsável escuta, sem corrigir o gosto ou exigir uma resposta certa.'),
('Uma ideia também traz consequências.','Se o vilão muda de lado, quem vira o desafio? A conversa pode seguir pela história que seu filho está inventando.','Rascunho original de dois personagens e uma mudança na relação, adequado a 9–14 anos.'),
('Criar jogos dá um caminho para transformar ideias em escolhas.','Num jogo de aventura, a criança pode inventar o objetivo e o que atrapalha o personagem. A programação faz as ações acontecerem para alguém jogar essa criação.','Aventura do Herói como base visual. Qualquer novo objetivo ou enredo é adaptação a produzir; não atribuir história inventada à versão existente.')
], 'Criatividade não aparece só quando a criança desenha ou começa algo do zero. Ela também pode aparecer numa conversa depois de um filme.\n\nAo imaginar outro final, seu filho usa uma história conhecida para propor uma mudança. Ouvir o motivo ajuda a conhecer a ideia por trás dela.\n\nCriar jogos pode aprofundar essa vontade de inventar: a criança decide um objetivo, pensa nos obstáculos e usa a programação para fazer essas escolhas funcionarem. Outra pessoa consegue experimentar a aventura.\n\nEla ganha um projeto em que a imaginação precisa tomar forma, com decisões que mudam a experiência de quem joga.',cta='Reconhecer uma ideia própria numa conversa sobre uma história.',delivery='Reflexão')

C('P13',[
('Ele explica a regra. Você termina sem entender como joga.','Seu filho conhece tão bem aquela brincadeira que pula as partes que parecem óbvias para ele. Para você, elas ainda fazem falta.','Criança explica jogo de cartas à família numa mesa. Usar cartas genéricas, sem mascotes infantis ou material escolar montado só para a foto.'),
('Pode ter faltado o começo da partida.','Você já ouviu como ganhar. Ainda não sabe quantas cartas pode virar na sua vez.','Mesa com cartas de memória viradas para baixo e adulto indicando duas delas.'),
('Diga qual informação falta.','“Na minha vez, eu viro uma ou duas?” Ele consegue completar uma parte específica da explicação.','Adulto faz pergunta e criança mostra a vez com duas cartas.'),
('Agora ele precisa pensar em quem está aprendendo.','A regra era conhecida por ele. Explicá-la para outra pessoa exige escolher por onde começar e quais detalhes contar.','Criança reorganiza explicação ao adulto. Não usar setas ou listas abstratas no lugar da interação.'),
('Programar um jogo trabalha essa clareza de outro jeito.','No jogo da memória, o computador precisa receber a regra: virar duas cartas, comparar as figuras e esconder de novo se forem diferentes. A criança organiza as instruções e testa se faltou alguma.','Exemplo Jogo da Memoria. Captar par diferente sendo ocultado e par igual mantido; não associar a curso vendido.')
], 'Explicar uma regra para quem nunca jogou exige perceber o que a outra pessoa ainda não sabe. A dúvida dela mostra qual informação ficou de fora.\n\n“Na minha vez, viro uma ou duas?” dá à criança um ponto claro para completar.\n\nCriar jogos pode trabalhar essa habilidade porque programar exige dizer o que acontece em cada situação. No jogo da memória, cartas iguais e diferentes pedem respostas diferentes.\n\nA criança precisa organizar essas regras para que a partida funcione. Depois, pode observar outra pessoa jogar e descobrir o que ainda falta explicar.',cta='Mostrar uma informação que falta na explicação para quem está chegando.')

C('P15',[
('Seu filho pediu opinião. Você ficou no “gostei”.','Ele ensaiou a apresentação da escola. Você gostou, mas percebeu uma parte confusa e não sabe como ajudar.','Filho ensaia apresentação escolar para responsável; notebook e caderno, sem figurino ou palco artificial.'),
('Escolham um ponto para conferir.','“Deu para entender por que esse animal vive nesse lugar?” Agora você sabe qual parte da explicação ouvir.','Página escolar sobre habitat com imagem própria ou licenciada; criança explica ao adulto.'),
('Conte o que você conseguiu acompanhar.','“Entendi onde ele vive. Não entendi o que ele encontra ali para comer.” Essa diferença mostra o trecho que ficou faltando.','Adulto aponta imagem do habitat e criança consulta anotações sobre alimentação.'),
('Ele pode completar a própria explicação.','Seu filho escolhe uma informação e ensaia de novo. A opinião virou uma ajuda que dá para usar.','Criança acrescenta uma anotação e retoma fala; adulto não reescreve tudo por ela.'),
('Criar jogos dá um motivo para ouvir quem vai usar.','Num jogo de perguntas, outra pessoa pode entender uma questão de um jeito diferente. Quem criou observa a dúvida, melhora o texto e testa de novo.','Quiz de números como base para demonstrar pergunta e respostas. Ambiguidade deve ser variação preparada pela equipe, não problema atribuído ao original.')
], 'Uma opinião ajuda mais quando mostra o que a outra pessoa entendeu e em qual ponto se perdeu.\n\nNo ensaio da apresentação escolar, vocês podem escolher uma parte para ouvir. Se faltou explicar a alimentação do animal, há algo específico para acrescentar.\n\nCriar jogos também oferece esse contato com quem vai usar a criação. Num jogo de perguntas, o autor precisa considerar como o jogador lê e escolhe uma resposta.\n\nOuvir essa pessoa e ajustar a pergunta dá uma experiência concreta de melhorar algo a partir de uma opinião.',cta='Dar retorno sobre um ponto específico de uma apresentação ou criação.')

C('P16',[
('Ele refez a conta. O resultado errado apareceu de novo.','Seu filho apagou e começou do início. Mas repetiu o mesmo passo que estava causando a dificuldade.','Caderno de matemática com exercício refeito. Criança de 10–13 anos olha para a conta; sem nota vermelha ou humilhação.'),
('“Faz de novo” ainda não mostra o que precisa mudar.','Peça que ele explique a conta linha por linha. Vocês podem comparar com o exemplo feito na aula.','Duas contas lado a lado: exemplo da aula e tentativa. Valores só entram depois de conferir a matemática.'),
('Procurem o primeiro passo que ficou diferente.','Pode ser um sinal copiado errado ou uma etapa que não entendeu. Se vocês não souberem, marquem esse ponto para pedir ajuda.','Criança aponta um sinal diferente no próprio caderno, adulto acompanha sem assumir o lápis.'),
('A próxima tentativa ganha um motivo.','Agora ele volta àquela etapa. Se estiver frustrado, uma pausa pode vir antes de continuar.','Caderno marcado para retomar; criança revisa uma linha, sem encenação de transformação emocional.'),
('Criar jogos também pede encontrar o que está impedindo uma ideia de funcionar.','Se o personagem não alcança uma plataforma, a criança pode ajustar o pulo ou a distância. Ao mudar uma coisa por vez e jogar, consegue observar o efeito de cada escolha.','Mini plataforma como base: uma variação com destino a alcançar deve ser preparada e testada. Mostrar uma alteração por vez; não prometer esse desafio num curso específico.')
], 'Refazer uma conta inteira pode repetir a mesma dúvida. O passo que a criança não entendeu continua ali.\n\nAcompanhar a resolução ajuda a localizar onde pedir outra explicação. Vocês podem usar um exemplo da aula como referência e marcar o primeiro ponto que ficou diferente.\n\nCriar jogos pode ser uma forma de praticar a investigação de problemas, porque a criança vê o efeito das instruções que montou. Um personagem que não chega à plataforma dá um resultado para examinar.\n\nEla escolhe uma mudança, testa e compara. Existe um motivo para tentar de novo, além de repetir o esforço. Isso complementa outras experiências de aprendizagem; não substitui o ensino de matemática.',cta='Localizar a etapa da dificuldade antes de repetir toda a tarefa.')

R('P17','Ele quis mudar uma coisa no vídeo. O resultado ficou outro.',[
('Criança edita vídeo caseiro autorizado da família ou do próprio animal, sem rede social aberta.','O mesmo vídeo, dois começos.','Seu filho gravou um vídeo e quer tirar um pedaço do começo. Antes de apagar tudo, ele compara o trecho inteiro com uma versão mais curta.'),
('Reproduzir original e versão cortada. Manter som e demais elementos iguais.','Mudou só o corte.','Se mudar corte, música e velocidade de uma vez, fica difícil perceber o efeito de cada escolha. Comparar só o começo deixa a diferença mais clara.'),
('Responsável assiste e ouve o motivo da escolha.','Agora ele tem um motivo para escolher.','A parte importante ficou mais fácil de encontrar? Faltou entender o que estava acontecendo? A criança pode ouvir sua impressão e decidir o que prefere.'),
('Quebra-blocos: mesma cena com duas velocidades preparadas pela equipe.','Criar jogos permite experimentar escolhas e comparar.','Num jogo de rebater a bola, aumentar a velocidade muda o tempo para reagir. Quem cria pode testar duas versões e decidir qual partida faz mais sentido. A mudança tem um efeito que dá para observar.')
], 'Quando a criança edita um vídeo, pode fazer várias mudanças antes de assistir ao resultado. Comparar uma alteração por vez ajuda a entender o que cada escolha fez.\n\nIsso dá uma conversa concreta: o corte deixou a ação mais clara ou tirou uma parte necessária?\n\nCriar jogos oferece outra oportunidade de experimentar ideias dessa forma. No Quebra-blocos, a equipe pode preparar duas velocidades da bola. Quem programa observa como isso muda a dificuldade antes de escolher a versão.\n\nA curiosidade ganha um método simples: mudar, comparar e explicar a preferência.',delivery='Curiosidade e reflexão',skill='Comparação de versões: perceber o efeito de uma mudança.',cta='Comparar uma alteração por vez e ouvir o motivo da escolha.',proof='Exemplo Quebra-blocos registrado em game-2d-advanced; velocidade da bola faz parte do projeto. A variante será preparada antes da captação.',note='Usar vídeo caseiro autorizado. Não exigir publicação da criança. Demonstrar as duas versões de fato; manter as demais condições iguais.')

C('P19',[
('Ele parou no trabalho. Amanhã vai tentar lembrar onde estava.','O texto está pela metade, as imagens estão numa pasta e chegou a hora de sair. Um recado para si mesmo ajuda a deixar o começo da volta.','Trabalho escolar no computador, arquivo salvo e caderno ao lado. Sem dados de escola ou aluno real.'),
('Anote o que já está pronto.','“Já escrevi onde o animal vive e o que ele come.” A frase lembra o que não precisa refazer.','Caderno com anotação literal ao lado da apresentação escolar.'),
('Deixe uma tarefa para a volta.','“Falta escolher uma imagem para mostrar como ele se desloca.” É mais claro do que escrever só “continuar o trabalho”.','Segunda anotação junto do material. Imagem ainda a escolher, sem mostrar mecanismo inexistente no programa.'),
('Antes de fechar, confira se o arquivo ficou salvo.','O recado guarda a próxima ideia. O salvamento guarda o que ele já fez.','Responsável e criança conferem o salvamento real da ferramenta usada na apresentação.'),
('Aprender a criar jogos também envolve continuar um projeto depois.','Num jogo de fazenda, ele pode montar o plantio numa etapa e deixar o teste do crescimento para a próxima. Registrar o que falta dá um começo para retomar a criação.','Fazenda Feliz, com estados de terra, broto e planta madura. Referência de planejamento de projeto, não promessa de recurso de tarefa no editor.')
], 'Um trabalho pode continuar em outro dia. O que atrapalha é voltar e precisar descobrir de novo onde tinha parado.\n\nUma anotação com o que está pronto e o que falta ajuda a guardar essa decisão. “Escolher uma imagem para explicar o deslocamento” aponta uma tarefa; “continuar” ainda deixa tudo em aberto.\n\nNa criação de jogos, o mesmo cuidado acompanha um projeto que cresce por etapas. Um jogo de fazenda tem plantio, crescimento e colheita para construir e conferir.\n\nA criança pode registrar o próximo teste e retomar dali. Antes de fechar, confiram também o salvamento da ferramenta utilizada.',cta='Salvar o trabalho e anotar uma próxima ação específica.')

I('P21','Seu filho também pode ensinar uma coisa a você.','“Me mostra como você fez isso.”','Filho mostra ao responsável como recortou um vídeo caseiro no computador. Adulto observa o trecho e a ferramenta usada; sem fingir que não sabe mexer para provocar a cena.',
'Seu filho colocou uma legenda num vídeo ou encontrou um jeito de organizar as fotos. Você ainda não conhece aquele recurso e pede que ele mostre.\n\nA conversa muda de lugar: agora ele precisa explicar e você pode dizer onde ficou com dúvida.\n\nCriar um mundo ou um jogo dá outras oportunidades para essa troca. A criança toma decisões sobre o cenário, os caminhos e as ações; depois, apresenta algo que ajudou a construir.\n\nAo pedir que mostre essas escolhas, você participa do interesse dele e abre espaço para que ele também ensine.',cta='Se interessar por uma descoberta que o filho queira mostrar.')

C('P22',[
('Ele seguiu um tutorial. Depois quis fazer do jeito dele.','Seu filho aprende um desenho pelo vídeo. Na segunda tentativa, troca a roupa do personagem, muda o cabelo e inventa outra expressão.','Adolescente de 12–14 anos desenha personagem original a partir de tutorial próprio, com duas versões. Evitar origami ou estética pré-escolar.'),
('O exemplo ensinou por onde começar.','Ele observou as formas e experimentou os traços. Agora tem uma referência para fazer escolhas.','Detalhe de esboço de rosto e segunda tentativa, sem exigir desenho profissional.'),
('A diferença tem uma intenção.','“Quero que pareça mais bravo.” A criança muda as sobrancelhas e vê se a expressão ficou como imaginou.','Duas expressões do mesmo personagem original. Sobrancelhas em destaque apenas como exemplo, sem promessa de método de desenho.'),
('Uma escolha própria pode nascer depois de aprender o básico.','Vale ouvir o que ele quis mudar. O exemplo pode dar apoio para criar outra versão.','Responsável observa os dois desenhos e criança aponta a alteração.'),
('Na programação, uma regra conhecida também pode virar uma nova ideia.','Depois de entender a Cobrinha, quem cria pode experimentar outra velocidade ou mudar o tamanho do espaço. O teste mostra como a escolha muda a partida.','Cobrinha do Estúdio. Preparar duas variações reais; tamanho do tabuleiro e velocidade não são botões prometidos, são ajustes no projeto.')
], 'Aprender por um exemplo pode dar à criança uma forma de começar. Depois, ela enxerga o que gostaria de mudar.\n\nNum desenho, a intenção pode ser outra expressão. Num jogo, pode ser uma partida mais rápida ou um espaço menor para se mover.\n\nCriar jogos trabalha essa passagem da referência para a escolha própria: a criança entende uma regra, modifica uma parte e experimenta o efeito.\n\nA criatividade aparece na intenção e na versão que ela constrói, sem exigir que invente tudo do zero.',cta='Ouvir a intenção de uma mudança feita a partir de uma referência.')

I('P24','Ele tem assunto para a apresentação. Falta colocar em ordem.','O que vou explicar.\nUm exemplo para mostrar.\nO que a turma precisa lembrar.','Três partes de uma apresentação escolar sobre reciclagem: separação de resíduos, exemplo de garrafa destinada à coleta, recado para consultar as orientações locais. Não representar cores ou destinação como universais.',
'Seu filho pesquisou, juntou imagens e agora não sabe por onde começar a apresentação. Uma lista curta pode organizar a fala.\n\nEscolham o que ele vai explicar, um exemplo que ajude a entender e a ideia que quer deixar com a turma. Depois, ele ensaia olhando para esses pontos.\n\nCriar jogos também exige dar uma ordem ao que será apresentado. No Pong, quem vai jogar precisa saber que controla uma raquete, que deve rebater a bola e como a partida termina.\n\nAo escrever essas orientações e ver alguém jogar, a criança percebe se deixou uma informação importante para trás.',cta='Organizar uma apresentação em explicação, exemplo e ideia principal.')

R('P26','Ele diz que não gosta de conta. Mas confere cada ponto da partida.',[
('Filho e responsável assistem ou comentam futebol; usar placar próprio, sem vídeo de transmissão.','“Se ganhar, vai para quantos pontos?”','Seu filho acompanha um campeonato e quer saber quantos pontos o time terá se vencer a próxima partida. A conta responde a uma dúvida que interessa a ele.'),
('Tabela fictícia claramente simples, time com 10 pontos e vitória somando 3.','Dez pontos, mais três: treze.','Na tabela do exemplo, o time tem dez pontos e a vitória vale três. Somar dá o resultado que ele quer comparar com os outros times.'),
('Responsável conversa sobre o cálculo, sem mostrar boletim ou prometer mudança escolar.','Um motivo para conferir a conta.','Esse interesse não elimina dificuldades em matemática. Ele oferece uma situação em que vale descobrir o resultado e explicar como chegou nele.'),
('Corrida Maluca no Estúdio: mostrar volta completa alterando contador.','Criar um jogo exige fazer a contagem funcionar.','Num jogo de corrida, quem programa precisa definir quando uma volta conta. Depois, testa se o placar corresponde ao que aconteceu. O número tem uma função que a criança consegue conferir.')
], 'A criança pode querer fazer uma conta para descobrir a posição do time, comparar pontos ou saber o que falta para alcançar outro jogador.\n\nIsso não torna toda tarefa de matemática fácil. Mas dá um motivo concreto para calcular e conferir.\n\nCriar jogos amplia essa experiência: a criança passa a construir a própria contagem. Num jogo de corrida, precisa decidir quando uma volta é completada e verificar se o placar soma corretamente.\n\nA programação liga o número a uma ação. O exemplo visual será Corrida Maluca, do Estúdio, que conta voltas completas.',cta='Conhecer um uso dos números que interessa ao filho.',proof='Corrida Maluca, game-3d/examples.ts: descrição e projeto contam voltas completas. A tabela de futebol é um exemplo inventado, não classificação real.')

C('P27',[
('Dois trabalhos prontos podem esconder caminhos bem diferentes.','Numa apresentação, a criança escolheu as informações e explicou com suas palavras. Na outra, ainda precisou de ajuda para entender o que colocou.','Duas apresentações escolares parecidas, sem nomes, notas ou julgamento visual de melhor e pior.'),
('A aparência mostra só uma parte.','Imagens bonitas e texto bem alinhado não contam como seu filho escolheu o conteúdo.','Slide escolar visualmente arrumado e anotações da pesquisa ao lado.'),
('Peça que ele explique uma escolha.','“Por que você colocou essa imagem?” Ele pode mostrar como ela ajuda a entender o assunto.','Criança aponta a relação entre imagem e informação da apresentação.'),
('Ouça também onde ainda precisou de ajuda.','Talvez saiba explicar, mas tenha dificuldade para escrever. Talvez use o programa com facilidade e ainda precise entender o texto. São apoios diferentes.','Responsável conversa sobre conteúdo e uso da ferramenta, sem medir a criança por uma única resposta.'),
('Criar jogos deixa algumas decisões disponíveis para experimentar.','No jogo da memória, seu filho pode mostrar por que cartas iguais ficam abertas e as diferentes voltam a esconder. Jogar e explicar a regra dá pistas sobre o que ele compreendeu.','Jogo da Memoria, mesma regra comprovada no exemplo. Não chamar a demonstração de avaliação completa da aprendizagem.')
], 'O trabalho pronto não mostra sozinho o que a criança entendeu ou de que ajuda precisou.\n\nPedir que explique uma escolha abre essa conversa. Uma imagem pode ter sido escolhida porque ajuda a entender o assunto ou só porque apareceu primeiro na busca. Vale ouvir o motivo.\n\nCriar jogos pode tornar decisões parecidas mais visíveis: a criança programa uma regra, vê o resultado e consegue mostrar como funciona.\n\nNo jogo da memória, comparar cartas iguais e diferentes dá uma demonstração concreta para conversar sobre a lógica. São pistas daquele momento, sem transformar a conversa numa prova.',cta='Conversar sobre uma escolha e a ajuda necessária, além da aparência da entrega.')

